<?php
namespace App\Http\Controllers;
use App\Http\Requests\StoreProductRequest;use App\Http\Requests\UpdateProductRequest;use App\Models\Product;use Illuminate\Contracts\View\View;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use PhpOffice\PhpSpreadsheet\IOFactory;use PhpOffice\PhpSpreadsheet\Spreadsheet;use PhpOffice\PhpSpreadsheet\Writer\Xlsx;use Symfony\Component\HttpFoundation\StreamedResponse;
class ProductController extends Controller
{
 public function index(Request $r): View{$f=$r->validate(['keyword'=>['nullable','string','max:255'],'status'=>['nullable','in:active,inactive']]);$products=Product::query()->when($f['keyword']??null,fn($q,$k)=>$q->where(fn($s)=>$s->where('material_code','like',"%{$k}%")->orWhere('material_name','like',"%{$k}%")->orWhere('unit','like',"%{$k}%")))->when(($f['status']??null)==='active',fn($q)=>$q->where('is_active',true))->when(($f['status']??null)==='inactive',fn($q)=>$q->where('is_active',false))->orderBy('material_code')->paginate(20)->withQueryString();return view('products.index',['products'=>$products,'filters'=>$f]);}
 public function create(): View{return view('products.create');} public function store(StoreProductRequest $r): RedirectResponse{Product::create($r->validated());return redirect()->route('products.index')->with('success','Đã tạo sản phẩm.');} public function edit(Product $product): View{return view('products.edit',compact('product'));} public function update(UpdateProductRequest $r,Product $product): RedirectResponse{$product->update($r->validated());return redirect()->route('products.index')->with('success','Đã cập nhật sản phẩm.');} public function destroy(Product $product): RedirectResponse{$product->delete();return back()->with('success','Đã xóa sản phẩm.');}
 public function import(Request $r): RedirectResponse{$r->validate(['import_file'=>['required','file','mimes:xlsx,xls','max:10240']]);$rows=IOFactory::load($r->file('import_file')->getRealPath())->getActiveSheet()->toArray(null,true,true,false);if(count($rows)<2)return back()->withErrors(['import_file'=>'File Excel không có dữ liệu.']);$h=array_map(fn($v)=>mb_strtolower(trim((string)$v)),array_shift($rows));$a=['material_code'=>['mã vật tư','ma_vat_tu','material_code'],'material_name'=>['tên vật tư','ten_vat_tu','material_name'],'unit'=>['đơn vị tính','đvt','unit'],'standard_weight_g'=>['định mức g/đvt','standard_weight_g'],'default_length_m'=>['chiều dài mặc định (m)','chiều dài mặc định','default_length_m'],'is_active'=>['trạng thái','is_active'],'notes'=>['ghi chú','notes']];$p=[];foreach($a as $f=>$ns)foreach($ns as $n){$i=array_search(mb_strtolower($n),$h,true);if($i!==false){$p[$f]=$i;break;}}foreach(['material_code','material_name','unit'] as $f)if(!isset($p[$f]))return back()->withErrors(['import_file'=>'Thiếu cột Mã vật tư, Tên vật tư hoặc Đơn vị tính.']);$c=$u=$s=0;foreach($rows as $row){$g=fn($f)=>isset($p[$f])?trim((string)($row[$p[$f]]??'')):'';$code=mb_strtoupper($g('material_code'));if($code===''||$g('material_name')===''||$g('unit')===''){$s++;continue;}$payload=['material_name'=>$g('material_name'),'unit'=>$g('unit'),'standard_weight_g'=>$this->num($g('standard_weight_g')),'default_length_m'=>$this->num($g('default_length_m')),'is_active'=>!in_array(mb_strtolower($g('is_active')),['0','false','inactive','ngừng','không hoạt động'],true),'notes'=>$g('notes')?:null];$x=Product::withTrashed()->where('material_code',$code)->first();if($x){$x->restore();$x->update($payload);$u++;}else{Product::create($payload+['material_code'=>$code]);$c++;}}return back()->with('success',"Nhập Excel hoàn tất: thêm {$c}, cập nhật {$u}, bỏ qua {$s} dòng.");}
 public function export(): StreamedResponse{return response()->streamDownload(function(){$s=new Spreadsheet();$sh=$s->getActiveSheet();$sh->setTitle('Danh muc san pham');$sh->fromArray(['Mã vật tư','Tên vật tư','Đơn vị tính','Định mức g/ĐVT','Chiều dài mặc định (m)','Trạng thái','Ghi chú'],null,'A1');$r=2;foreach(Product::orderBy('material_code')->get() as $x){$sh->fromArray([$x->material_code,$x->material_name,$x->unit,(float)$x->standard_weight_g,(float)$x->default_length_m,$x->is_active?'Hoạt động':'Ngừng',$x->notes],null,"A{$r}");$r++;}$sh->getStyle('A1:G1')->getFont()->setBold(true);foreach(range('A','G') as $c)$sh->getColumnDimension($c)->setAutoSize(true);(new Xlsx($s))->save('php://output');},'danh-muc-san-pham-'.now()->format('Ymd-His').'.xlsx',['Content-Type'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']);}
 private function num(string $v): ?float{if($v==='')return null;$v=str_replace(' ','',$v);if(str_contains($v,',')&&!str_contains($v,'.'))$v=str_replace(',','.',$v);return is_numeric($v)?(float)$v:null;}
}
